// FILTRES
// ============================================================
function updateFilterDropdowns(){
  fillFilterSel("fil-phase","Phase_Projet",filterPhase);
  fillFilterSel("fil-besoin","Besoin_Client",filterBesoin);
  fillFilterSel("fil-risque","Risque_Type",filterRisque);
  fillFilterSel("fil-application","Application",filterApplication);
}
function fillFilterSel(elId,cat,current){
  var el=document.getElementById(elId);if(!el)return;
  el.innerHTML="";
  var all=document.createElement("option");
  all.value="";
  all.textContent=({Phase_Projet:"Phase Projet",Besoin_Client:"Besoin Client",Risque_Type:"Risque",Application:"Application"})[cat]||cat;
  el.appendChild(all);
  state.acronymes.filter(function(a){return a.categorie===cat;})
    .sort(function(a,b){return(a.ordre||0)-(b.ordre||0);})
    .forEach(function(a){
      var opt=document.createElement("option");
      opt.value=a.id;
      opt.textContent=a.id+"  "+a.designation;
      if(a.id===current)opt.selected=true;
      el.appendChild(opt);
    });
}
function nodeMatchesFilters(node){
  if(filterPhase&&node.phase!==filterPhase)return false;
  if(filterBesoin&&node.besoin!==filterBesoin)return false;
  if(filterRisque&&node.risque!==filterRisque)return false;
  if(filterApplication&&node.application!==filterApplication)return false;
  return true;
}
function subtreeMatchesFilters(node){
  if(nodeMatchesFilters(node))return true;
  for(var i=0;i<node.children.length;i++){if(subtreeMatchesFilters(node.children[i]))return true;}
  return false;
}

// ============================================================
// PROFONDEUR
// ============================================================
var depthLimit=null;
function updateDepthBar(){
  var maxD=0;
  allNodes.forEach(function(n){if(n.niveau>maxD)maxD=n.niveau;});
  var bar=document.getElementById("depth-bar");
  bar.innerHTML="<span>Deployer jusqu au niveau :</span>";
  for(var d=1;d<=maxD;d++){
    (function(dd){
      var b=document.createElement("button");
      b.className="dbtn";
      b.textContent=dd;
      b.title="Deployer l arbre jusqu au niveau "+dd;
      b.onclick=function(){setDepth(dd);};
      bar.appendChild(b);
    })(d);
  }
}
function setDepth(d){
  // Deploiement (pas filtre) : ouvrir l'arbre jusqu'au niveau d, puis laisser le manuel
  if(d===null){
    // "Tout" : tout deployer
    openNodes={};
    allNodes.forEach(function(n){ if(n.children&&n.children.length) openNodes[n.tvId]=1; });
  }else{
    openNodes={};
    // ouvrir les noeuds dont la profondeur < d (la racine est niveau 0)
    allNodes.forEach(function(n){
      if(n.children&&n.children.length){
        var prof=(n.tvId==="0")?0:n.tvId.split(".").length-1;
        if(prof<d) openNodes[n.tvId]=1;
      }
    });
    openNodes["0"]=1;
  }
  depthLimit=null; // on reste en mode manuel : les ouvertures manuelles fonctionnent ensuite
  updateDepthBar();renderTree();
}

