// ARBRE
// ============================================================
var selectedTvId=null, filterType="ALL", searchStr="", openNodes={"0":1};

function setFilter(f){
  filterType=f;
  document.getElementById("f-all").className=f==="ALL"?"a-all":"";
  document.getElementById("f-ef").className=f==="EF"?"a-ef":"";
  document.getElementById("f-cc").className=f==="CC"?"a-cc":"";
  renderTree();
}
function onSearch(v){searchStr=v.toLowerCase().trim();renderTree();}
function getMatchIds(){
  if(!searchStr)return null;
  var s={};
  allNodes.forEach(function(n){if((n.no+" "+n.idu+" "+n.dc+" "+n.chemin).toLowerCase().indexOf(searchStr)>=0)s[n.tvId]=1;});
  return s;
}
function renderTree(){
  renderFilterBanner();
  var c=document.getElementById("tree-scroll");
  c.innerHTML="";
  var m=getMatchIds(), acrMap=buildAcrMap();
  var inner=document.createElement("div");
  inner.style.display="inline-block";inner.style.minWidth="100%";
  treeRoots.forEach(function(r){renderNode(r,inner,0,m,acrMap);});
  c.appendChild(inner);
}

// Splitter FBS (redimensionnement tree/detail)
function initSplitterFBS(){
  var sp=document.getElementById("splitter-fbs");
  var left=document.getElementById("tree-panel");
  var main=document.getElementById("main");
  if(!sp||!left||!main)return;
  var dragging=false;
  sp.addEventListener("mousedown",function(e){dragging=true;e.preventDefault();document.body.style.userSelect="none";});
  document.addEventListener("mousemove",function(e){
    if(!dragging)return;
    var rect=main.getBoundingClientRect();
    var w=e.clientX-rect.left;
    if(w<200)w=200; if(w>rect.width-280)w=rect.width-280;
    left.style.width=w+"px";
  });
  document.addEventListener("mouseup",function(){dragging=false;document.body.style.userSelect="";});
}
function getActiveFiltersText(){
  var acrMap=buildAcrMap();
  var parts=[];
  if(filterType!=="ALL") parts.push({lbl:"Type",val:filterType});
  if(filterBesoin){var a=acrMap[filterBesoin];parts.push({lbl:"Besoin",val:(a?a.designation:filterBesoin)});}
  if(filterRisque){var a2=acrMap[filterRisque];parts.push({lbl:"Risque",val:(a2?a2.designation:filterRisque)});}
  if(filterApplication){var a4=acrMap[filterApplication];parts.push({lbl:"Application",val:(a4?a4.designation:filterApplication)});}
  if(filterPhase){var a3=acrMap[filterPhase];parts.push({lbl:"Phase",val:(a3?a3.designation:filterPhase)});}
  if(searchStr) parts.push({lbl:"Recherche",val:searchStr});
  return parts;
}
function renderFilterBanner(){
  var banner=document.getElementById("filter-banner");
  if(!banner) return;
  banner.innerHTML="";
  var parts=getActiveFiltersText();
  if(!parts.length){ banner.className=""; return; }
  banner.className="active";
  banner.appendChild(makeEl("span",{style:{fontSize:"9px",color:"var(--text3)",marginRight:"6px",textTransform:"uppercase"}},"Filtres actifs:"));
  parts.forEach(function(p){
    var chip=makeEl("span",{"class":"filter-chip"});
    chip.appendChild(makeEl("span",{},p.lbl+":"));
    chip.appendChild(makeEl("b",{},p.val));
    banner.appendChild(chip);
  });
  var clearBtn=makeEl("button",{"class":"btn",style:{fontSize:"9px",padding:"1px 6px",marginLeft:"4px"}},"Tout effacer");
  clearBtn.onclick=function(){
    filterType="ALL";filterBesoin="";filterRisque="";filterPhase="";filterApplication="";searchStr="";
    document.getElementById("f-all").className="a-all";
    document.getElementById("f-ef").className="";
    document.getElementById("f-cc").className="";
    document.getElementById("fil-phase").value="";
    document.getElementById("fil-besoin").value="";
    document.getElementById("fil-risque").value="";
    var fa=document.getElementById("fil-application");if(fa)fa.value="";
    document.getElementById("search").value="";
    renderTree();
  };
  banner.appendChild(clearBtn);
}
function renderNode(node,container,depth,matchIds,acrMap){
  if(filterType!=="ALL"&&node.typeId!=="ROOT"&&node.typeId!==filterType){
    if(node.children.length)node.children.forEach(function(c){renderNode(c,container,depth,matchIds,acrMap);});
    return;
  }
  var hasFilter=filterPhase||filterBesoin||filterRisque;
  if(hasFilter&&node.typeId!=="ROOT"&&!subtreeMatchesFilters(node))return;
  var isOpen=depthLimit===null?!!openNodes[node.tvId]:depth<depthLimit;
  var isMatch=matchIds&&matchIds[node.tvId];
  var isSel=selectedTvId===node.tvId;
  var indent=Math.min(depth*30,180);
  var hasFilter2=hasFilter&&nodeMatchesFilters(node)&&node.typeId!=="ROOT";
  var wrap=document.createElement("div");
  var row=document.createElement("div");
  var selCls=isSel?(node.typeId==="CC"?"sel-cc":node.typeId==="ROOT"?"sel-root":"sel-ef"):"";
  row.className="node-row "+selCls+(isMatch&&!isSel?" match":"")+(hasFilter2?" filter-match":"");
  row.style.paddingLeft=(indent+4)+"px";
  row.onclick=function(){selectNode(node.tvId);};
  // Drag and drop (sauf racine)
  if(node.typeId!=="ROOT"){
    row.draggable=true;
    row.ondragstart=function(e){
      e.dataTransfer.setData("text/plain",JSON.stringify({tvId:node.tvId,fbsId:node.fbsId,source:"tree"}));
      e.dataTransfer.effectAllowed="all";
      row.style.opacity="0.4";
    };
    row.ondragend=function(){row.style.opacity="1";};
  }
  // Zone de drop (tout noeud, y compris racine, peut recevoir)
  row.ondragover=function(e){
    e.preventDefault();e.dataTransfer.dropEffect="move";
    // Detecter moitie haute (avant) / basse (apres) / centre (dans)
    var rect=row.getBoundingClientRect();
    var rel=(e.clientY-rect.top)/rect.height;
    row.style.outline="";row.style.borderTop="";row.style.borderBottom="";
    if(rel<0.30){ row.style.borderTop="2px solid #14b8a6"; }
    else if(rel>0.70){ row.style.borderBottom="2px solid #14b8a6"; }
    else { row.style.outline="2px solid #3b82f6"; }
  };
  row.ondragleave=function(){row.style.outline="";row.style.borderTop="";row.style.borderBottom="";};
  row.ondrop=function(e){
    e.preventDefault();e.stopPropagation();
    var rect=row.getBoundingClientRect();
    var rel=(e.clientY-rect.top)/rect.height;
    row.style.outline="";row.style.borderTop="";row.style.borderBottom="";
    var data;try{data=JSON.parse(e.dataTransfer.getData("text/plain"));}catch(err){return;}
    if(!data)return;
    var dropMode = rel<0.30 ? "before" : (rel>0.70 ? "after" : null);
    handleDrop(data,node,dropMode);
  };
  // Menu contextuel clic droit
  row.oncontextmenu=function(e){
    e.preventDefault();e.stopPropagation();
    selectNode(node.tvId);
    showCtxMenu(e.clientX,e.clientY,node);
  };
  var tog=document.createElement("span");
  tog.className="tog";
  tog.textContent=node.children.length?(isOpen?"v":">"):" ";
  if(node.children.length)tog.onclick=function(e){e.stopPropagation();toggleNode(node.tvId);};
  row.appendChild(tog);
  var badge=document.createElement("span");
  var acrMapB=buildAcrMap();
  var typeAcr=acrMapB[node.typeId]||acrMapB["Racine"];
  if(node.typeId==="ROOT"){
    badge.className="badge broot";
    var rootAcr=acrMapB["Racine"];
    if(rootAcr&&acrIconSrc(rootAcr)){
      var ri=document.createElement("img");
      ri.src=acrIconSrc(rootAcr);
      ri.style.width="14px";ri.style.height="14px";ri.style.objectFit="contain";ri.style.verticalAlign="middle";
      badge.appendChild(ri);
    } else { badge.textContent="R"; }
  } else if(typeAcr&&acrIconSrc(typeAcr)){
    badge.className="badge-icon";
    var ti=document.createElement("img");
    ti.src=acrIconSrc(typeAcr);
    ti.style.width="18px";ti.style.height="18px";ti.style.objectFit="contain";ti.style.verticalAlign="middle";
    ti.title=typeAcr.designation||node.typeId;
    badge.appendChild(ti);
  } else {
    badge.className="badge "+(node.typeId==="CC"?"bcc":"bef");
    badge.textContent=node.typeId||"?";
  }
  row.appendChild(badge);
  if(node.typeId==="EF"){
    var sc=sowCountsFor(node.fbsId);
    if(sc.created>0){
      var sowAcrId=sc.complete>0?"SOW_V":"SOW_R";
      var sowAcr=acrMapB[sowAcrId];
      var sowWrap=document.createElement("span");
      sowWrap.style.display="inline-flex";sowWrap.style.alignItems="center";sowWrap.style.gap="2px";sowWrap.style.marginRight="3px";
      if(sowAcr&&acrIconSrc(sowAcr)){
        var si=document.createElement("img");si.src=acrIconSrc(sowAcr);si.style.width="14px";si.style.height="14px";si.style.objectFit="contain";si.style.flexShrink="0";sowWrap.appendChild(si);
      }else{
        var sd=document.createElement("span");sd.style.display="inline-block";sd.style.width="9px";sd.style.height="9px";sd.style.borderRadius="50%";sd.style.background=sc.complete>0?"#16a34a":"#dc2626";sd.style.flexShrink="0";sowWrap.appendChild(sd);
      }
      if(sc.complete>0)sowWrap.appendChild(makeEl("span",{style:{fontSize:"9px",fontWeight:"bold",color:"#16a34a"}},String(sc.complete)));
      sowWrap.title=(sc.complete>0?sc.complete+" BE ont une fiche SOW complete":"Fiche(s) SOW recue(s) mais incomplete(s)")+" ("+sc.created+" recue(s))";
      row.appendChild(sowWrap);
    }
  }
  if(node.idu){var idu=document.createElement("span");idu.className="nidu";idu.textContent=node.idu;idu.title=node.idu;row.appendChild(idu);}
  var name=document.createElement("span");
  name.className="nname "+(node.typeId==="CC"?"cc-tx":node.typeId==="ROOT"?"root-tx":"ef-tx")+(isMatch?" match-tx":"");
  name.textContent=node.no||node.chemin||node.tvId;
  name.title=node.chemin||node.no||"";
  row.appendChild(name);
  if(node.typeId!=="ROOT")row.appendChild(makePillsEl(node,acrMap));
  wrap.appendChild(row);
  if(isOpen&&node.children.length){
    var ch=document.createElement("div");
    ch.style.borderLeft="1px solid #2d374855";
    ch.style.marginLeft=(indent+18)+"px";
    node.children.forEach(function(c){renderNode(c,ch,depth+1,matchIds,acrMap);});
    wrap.appendChild(ch);
  }
  container.appendChild(wrap);
}
function toggleNode(tvId){if(openNodes[tvId])delete openNodes[tvId];else openNodes[tvId]=1;renderTree();}
function selectNode(tvId){selectedTvId=tvId;renderTree();renderDetail(nodeMap[tvId]);}

