function renderDetail(node){
  var panel=document.getElementById("detail-scroll");
  panel.innerHTML="";
  if(!node){
    var empty=makeEl("div",{"class":"d-empty"});
    empty.appendChild(makeEl("div",{style:{fontSize:"40px",opacity:".15"}},"?"));
    empty.appendChild(makeEl("p",{},"Selectionnez un noeud dans l arbre"));
    panel.appendChild(empty);
    return;
  }
  var acrMap=buildAcrMap();
  // Racine : nom du projet + mission editables (identifiant fixe "UrBizia")
  if(node.typeId==="ROOT"){
    var rh=makeEl("div",{style:{padding:"14px"}});
    var rhdr=makeEl("div",{style:{display:"flex",alignItems:"center",gap:"8px",marginBottom:"12px"}});
    rhdr.appendChild(makeEl("span",{style:{fontSize:"13px",fontWeight:"bold",color:"#fca5a5"}},"Racine du projet"));
    rhdr.appendChild(makeEl("span",{style:{fontSize:"10px",fontFamily:"monospace",color:"var(--text3)",border:"1px solid var(--border2)",borderRadius:"4px",padding:"1px 6px"}},"UrBizia"));
    rh.appendChild(rhdr);
    rh.appendChild(makeEl("label",{style:{fontSize:"11px",color:"var(--text2)",display:"block",marginBottom:"4px"}},"Nom du projet"));
    var rno=makeEl("input",{style:{width:"100%",boxSizing:"border-box",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"7px 8px",color:"var(--text)",fontSize:"13px",outline:"none",marginBottom:"14px"}});
    rno.value=state.rootName||node.no||"";
    rh.appendChild(rno);
    rh.appendChild(makeEl("label",{style:{fontSize:"11px",color:"var(--text2)",display:"block",marginBottom:"4px"}},"Mission / contexte produit (insere en tete des prompts exportes)"));
    var rta=makeEl("textarea",{style:{width:"100%",minHeight:"220px",boxSizing:"border-box",background:"var(--bg3)",border:"1px solid var(--border2)",borderRadius:"6px",padding:"8px",color:"var(--text)",fontSize:"12px",lineHeight:"1.5",outline:"none"}});
    rta.value=state.rootMission||"";
    rh.appendChild(rta);
    var rrow=makeEl("div",{style:{marginTop:"10px",display:"flex",alignItems:"center",gap:"10px"}});
    var rbtn=makeEl("button",{"class":"btn primary",style:{fontSize:"12px",padding:"7px 18px"}},"Sauvegarder");
    var rsaved=makeEl("span",{style:{fontSize:"10px",color:"#16a34a",opacity:"0"}},"Enregistre");
    rbtn.onclick=function(){state.rootName=rno.value.trim();state.rootMission=rta.value;persist();computeNodes();renderTree();rsaved.style.opacity="1";setTimeout(function(){rsaved.style.opacity="0";},1500);};
    rrow.appendChild(rbtn);rrow.appendChild(rsaved);rh.appendChild(rrow);
    panel.appendChild(rh);
    return;
  }
  var f=state.fbs.find(function(x){return x.id===node.fbsId;});
  if(!f){panel.innerHTML="";return;}
  var isCC=(f.typeId==="CC");

  var wrap=makeEl("div",{style:{padding:"12px"}});

  // En-tete : badge type + IDU + indicateur edition
  var hdr=makeEl("div",{style:{display:"flex",alignItems:"center",gap:"8px",marginBottom:"10px",flexWrap:"wrap"}});
  var tAcr=acrMap[f.typeId];
  if(tAcr&&acrIconSrc(tAcr)){
    hdr.appendChild(makeEl("img",{src:acrIconSrc(tAcr),style:{width:"22px",height:"22px",objectFit:"contain"}}));
  }
  hdr.appendChild(makeEl("span",{style:{fontSize:"13px",fontWeight:"bold",color:isCC?"#5eead4":"#60a5fa"}},isCC?"Contrainte de Conception":"Ensemble Fonctionnel"));
  if(f.idu)hdr.appendChild(makeEl("span",{style:{fontSize:"10px",fontFamily:"monospace",color:"var(--text3)",border:"1px solid var(--border2)",borderRadius:"4px",padding:"1px 6px"}},f.idu));
  wrap.appendChild(hdr);

  // Bloc 2 colonnes
  var grid=makeEl("div",{"class":"edit-2col"});
  var col1=makeEl("div",{"class":"edit-col"});
  var col2=makeEl("div",{"class":"edit-col"});
  // Colonne 1 : Type, Identifiant, Nom (3 lignes)
  var typeCycle=makeCycleField("Type FBS","FBS_Type",f.typeId||"EF",{noNeutre:true,onlyVals:["EF","CC"],onChange:function(v){applyTypeVis(v);}});
  col1.appendChild(typeCycle);
  var iduFF=makeFF("Identifiant personnalise",makeInput("d-idu",f.idu||""));col1.appendChild(iduFF);
  var noFF=makeFF(isCC?"Objectif":"Nom",makeTextarea("d-no",f.no||""));noFF.className="ff full ff-nom";col1.appendChild(noFF);
  // Colonne 2 : Application, Besoin, Risque, Phase
  var aCy=makeCycleField("Application","Application",f.application||"");col2.appendChild(aCy);
  var bCy=makeCycleField("Besoin Client","Besoin_Client",f.besoin||"");col2.appendChild(bCy);
  var rCy=makeCycleField("Risque","Risque_Type",f.risque||"");col2.appendChild(rCy);
  var pCy=makeCycleField("Phase Projet","Phase_Projet",f.phase||"");col2.appendChild(pCy);
  grid.appendChild(col1);grid.appendChild(col2);
  wrap.appendChild(grid);

  // Description (mise en evidence) + Lignes Guides (normal) -- pleine largeur
  var dcFF=makeFF(isCC?"Contrainte":"Description",makeTextarea("d-dc",f.dc||""));
  dcFF.className="ff full ff-tall ff-highlight";
  var lgFF=makeFF("Lignes Guides",makeTextarea("d-lg",f.lg||""));
  lgFF.className="ff full ff-tall";
  var ecoFF=makeFF("Contraintes economiques",makeTextarea("d-eco",f.eco||""));
  ecoFF.className="ff full";
  var ecoScopeWrap=makeEl("div",{style:{display:"flex",alignItems:"center",gap:"8px",marginTop:"4px"}});
  ecoScopeWrap.appendChild(makeEl("label",{style:{fontSize:"10px",color:"var(--text3)",margin:"0"}},"Portee :"));
  ecoScopeWrap.appendChild(makeSelect("d-eco-scope",[{v:"self",l:"Cet EF seul"},{v:"tree",l:"Cet EF + sa sous-arborescence"}],f.ecoScope||"self"));
  ecoFF.appendChild(ecoScopeWrap);
  var compW=makeCompetenceWidget(f.competences||[]);
  var docsW=makeDocumentsWidget(f.documents||[],f.illustrations||[]);
  app(wrap,dcFF,lgFF,ecoFF,compW,docsW);

  // Visibilite selon type : Phase pour EF seulement, Illustrations pour CC seulement
  function applyTypeVis(t){
    var cc=(t==="CC");
    pCy.style.display=cc?"none":"";
    ecoFF.style.display=cc?"none":"";
    var l1=noFF.querySelector("label");if(l1)l1.textContent=cc?"Objectif":"Nom";
    var l2=dcFF.querySelector("label");if(l2)l2.textContent=cc?"Contrainte":"Description";
  }
  applyTypeVis(f.typeId);

  // Bouton Sauvegarder
  var actRow=makeEl("div",{style:{display:"flex",alignItems:"center",gap:"10px",margin:"6px 0 14px"}});
  var saveBtn=makeEl("button",{"class":"btn primary",style:{fontSize:"12px",padding:"7px 18px"}},"Sauvegarder");
  var savedLbl=makeEl("span",{style:{fontSize:"10px",color:"#16a34a",opacity:"0"}},"Enregistre");
  saveBtn.onclick=function(){
    var idx=state.fbs.findIndex(function(x){return x.id===node.fbsId;});
    if(idx<0)return;
    var newType=typeCycle._getVal()||"EF";
    var _parId=_parentFbsIdOf(node);
    if(newType==="EF"&&_parId!==null){var _p=state.fbs.find(function(x){return x.id===_parId;});if(_p&&_p.typeId==="CC"){alert("Cet element est sous une Contrainte (CC) : il ne peut pas devenir un EF.");return;}}
    if(newType==="CC"){var _kids=state.pcrm.filter(function(l){return l.parentId===node.fbsId;}).map(function(l){return l.childId;});if(_kids.some(function(cid){return subtreeHasEF(cid);})){alert("Impossible de passer en CC : cet element contient des EF dans ses branches (un CC ne peut pas contenir d EF).");return;}}
    state.fbs[idx].typeId=newType;
    var ni=document.getElementById("d-idu").value.trim();
    state.fbs[idx].idu=ni;
    state.fbs[idx].no=document.getElementById("d-no").value;
    state.fbs[idx].dc=document.getElementById("d-dc").value;
    state.fbs[idx].lg=document.getElementById("d-lg").value;
    if(newType==="CC"){state.fbs[idx].eco="";state.fbs[idx].ecoScope="self";}
    else{var _e=document.getElementById("d-eco");state.fbs[idx].eco=_e?_e.value:"";var _es=document.getElementById("d-eco-scope");state.fbs[idx].ecoScope=_es?_es.value:"self";}
    state.fbs[idx].besoin=bCy._getVal();
    state.fbs[idx].risque=rCy._getVal();
    state.fbs[idx].application=aCy._getVal();
    state.fbs[idx].phase=(newType==="CC")?"":pCy._getVal();
    state.fbs[idx].competences=compW._getComps?compW._getComps():[];
    state.fbs[idx].documents=docsW._getDocs?docsW._getDocs():[];
    state.fbs[idx].illustrations=[];
    persist();computeNodes();renderTree();
    savedLbl.style.opacity="1";
    setTimeout(function(){savedLbl.style.opacity="0";},1500);
    // re-render pour refleter le nouveau type (labels/phase) si change
    renderDetail(nodeMap[node.tvId]||null);
  };
  actRow.appendChild(saveBtn);actRow.appendChild(savedLbl);
  wrap.appendChild(actRow);

  // ---- Lecture seule : autres emplacements (multi-parents) ----
  var others=allNodes.filter(function(n){return n.fbsId===node.fbsId&&n.fbsId!==0&&n.tvId!==node.tvId;});
  if(others.length){
    var ms=makeEl("div",{"class":"d-sec"});
    ms.appendChild(makeEl("div",{"class":"d-lbl"},"Cet element apparait aussi sous ("+others.length+") :"));
    ms.appendChild(makeEl("div",{style:{fontSize:"11px",color:"#86efac",marginBottom:"3px"}},"--> "+(node.chemin||"")));
    others.forEach(function(s2){ms.appendChild(makeEl("div",{style:{fontSize:"10px",color:"var(--text3)"}},s2.chemin));});
    wrap.appendChild(ms);
  }

  // ---- Reponses SOW recues (EF) ----
  if(f.typeId==="EF"){
    var reps=(state.sow||[]).filter(function(e){return e.fbsId===node.fbsId;});
    if(reps.length){
      var ss=makeEl("div",{"class":"d-sec"});
      ss.appendChild(makeEl("div",{"class":"d-lbl"},"Reponses SOW recues ("+reps.length+")"));
      reps.forEach(function(e){
        var card=makeEl("div",{style:{background:"var(--bg3)",border:"1px solid var(--border)",borderRadius:"6px",padding:"6px 8px",marginBottom:"6px"}});
        var h2=makeEl("div",{style:{display:"flex",alignItems:"center",gap:"6px",marginBottom:"3px"}});
        h2.appendChild(makeEl("span",{style:{display:"inline-block",width:"8px",height:"8px",borderRadius:"50%",background:sowComplete(e)?"#16a34a":"#dc2626"}}));
        h2.appendChild(makeEl("span",{style:{fontSize:"11px",fontWeight:"bold",color:"var(--text)"}},e.beNom||"BE"));
        if(e.date)h2.appendChild(makeEl("span",{style:{fontSize:"9px",color:"var(--text3)"}},e.date));
        card.appendChild(h2);
        card.appendChild(makeEl("div",{style:{fontSize:"10px",color:"var(--text2)",lineHeight:"1.5"}},"Savoir: "+sowLbl("savoir",e.savoir)+" | S-Faire: "+sowLbl("savoirFaire",e.savoirFaire)+" | Proto: "+sowLbl("prototype",e.prototype)+" | Demo: "+sowLbl("demonstrateur",e.demonstrateur)));
        if(e.ressources||e.delais)card.appendChild(makeEl("div",{style:{fontSize:"10px",color:"#93c5fd",marginTop:"2px"}},(e.ressources?e.ressources+" j ETP":"")+(e.ressources&&e.delais?"  -  ":"")+(e.delais?e.delais+" mois":"")));
        ss.appendChild(card);
      });
      wrap.appendChild(ss);
    }
  }

  panel.appendChild(wrap);
}

