      var rd=[];if(e.ressources)rd.push("Ressources : "+e.ressources+" j ETP");if(e.delais)rd.push("Delais : "+e.delais+" mois");
      if(rd.length)card.appendChild(makeEl("div",{style:{fontSize:"11px",color:"#93c5fd",marginTop:"2px"}},rd.join("   -   ")));
      bd.appendChild(card);
