function _effDocLink(dd){if(!dd)return "";return (dd.lien||"").trim();}
function _openDoc(dd){
  var t=_effDocLink(dd);
  if(!t){alert("Le lien ou le chemin n'a pas ete actualise dans la base FBS ; a vous de le retablir.");return;}
  var url=t;
  if(/^[a-zA-Z]:[\\\/]/.test(url)){url="file:///"+url.replace(/\\/g,"/");}
  else if(/^\\\\/.test(url)){url="file:"+url.replace(/\\/g,"/");}
  else if(!/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(url)){url="file:///"+url.replace(/\\/g,"/");}
  var w=null;try{w=window.open(url,"_blank");}catch(e){w=null;}
  if(!w){alert("Impossible d'ouvrir le document (fenetre bloquee, ou ouverture de fichier local non autorisee par le navigateur).\nCible : "+url+"\nSi le lien ou le chemin n'a pas ete actualise dans la base FBS, a vous de le retablir.");}
}
