function makeCompetenceWidget(currentComps){
  currentComps = (currentComps||[]).slice();
  var wrap=makeEl("div",{"class":"ff full"});
  wrap.appendChild(makeEl("label",{},"Competences Metier"));
  var box=makeEl("div",{style:{border:"1px solid var(--border2)",borderRadius:"6px",padding:"4px",background:"var(--bg3)",display:"flex",flexWrap:"wrap",gap:"4px",alignItems:"center",minHeight:"36px"}});
  var hiddenState={comps:currentComps};
  function renderTags(){
    box.innerHTML="";
    hiddenState.comps.forEach(function(c,i){
      var tag=makeEl("span",{style:{display:"inline-flex",alignItems:"center",gap:"4px",background:"#1e3a5f",color:"#93c5fd",border:"1px solid #2563eb44",borderRadius:"4px",padding:"1px 6px",fontSize:"10px"}},c);
      var x=makeEl("span",{style:{cursor:"pointer",color:"#f87171",fontWeight:"bold"}},"x");
      x.onclick=(function(idx){return function(){hiddenState.comps.splice(idx,1);renderTags();};})(i);
      tag.appendChild(x);
      box.appendChild(tag);
    });
    box.appendChild(inp);
  }
  var inp=makeEl("input",{placeholder:"Taper ou choisir...",style:{flex:"1",minWidth:"120px",border:"none",background:"transparent",color:"var(--text)",fontSize:"11px",outline:"none",fontFamily:"inherit"}});
  // datalist pour autocomplete
  var listId="comp-list-"+Math.random().toString(36).slice(2,7);
  inp.setAttribute("list",listId);
  var datalist=makeEl("datalist",{id:listId});
  function refreshDatalist(){
    datalist.innerHTML="";
    (state.competences||[]).forEach(function(c){
      datalist.appendChild(makeEl("option",{value:c}));
    });
  }
  refreshDatalist();
  function addComp(val){
    val=(val||"").trim();
    if(!val) return;
    if(hiddenState.comps.indexOf(val)<0) hiddenState.comps.push(val);
    // Ajouter a la liste maitresse si nouvelle
    if((state.competences||[]).indexOf(val)<0){
      state.competences.push(val);
      state.competences.sort();
      refreshDatalist();
      persist();
    }
    inp.value="";
    renderTags();
  }
  inp.onkeydown=function(e){
    if(e.key==="Enter"||e.key===","){e.preventDefault();addComp(this.value);}
    else if(e.key==="Backspace"&&this.value===""&&hiddenState.comps.length){hiddenState.comps.pop();renderTags();}
  };
  inp.onchange=function(){if(this.value)addComp(this.value);};
  renderTags();
  wrap.appendChild(box);
  wrap.appendChild(datalist);
  wrap._getComps=function(){return hiddenState.comps;};
  return wrap;
}


