var ctxNode = null;
function showCtxMenu(x, y, node){
  ctxNode = node;
  var menu = document.getElementById("ctx-menu");
  menu.style.display = "block";
  // Eviter le debordement ecran
  var mw = 190, mh = 200;
  if(x + mw > window.innerWidth) x = window.innerWidth - mw - 5;
  if(y + mh > window.innerHeight) y = window.innerHeight - mh - 5;
  menu.style.left = x + "px";
  menu.style.top = y + "px";
  // Si racine ou CC : pas d'ajout CC en-dessous d'un CC
  var btns = menu.querySelectorAll("button");
  // Les CC ne peuvent pas avoir d'enfants -> masquer les "ajouter en-dessous"
  var isCC = node.typeId === "CC";
  btns[0].style.display = isCC ? "none" : "block"; // + EF : interdit sous un CC
  btns[1].style.display = "block";                 // + CC : autorise partout (EF et CC)
}
function hideCtxMenu(){
  var menu = document.getElementById("ctx-menu");
  if(menu) menu.style.display = "none";
}
// Fermer le menu sur clic ailleurs
document.addEventListener("click", function(){ hideCtxMenu(); });
document.addEventListener("scroll", function(){ hideCtxMenu(); }, true);

function ctxAddChild(type){
  hideCtxMenu();
  if(!ctxNode) return;
  if(ctxNode.typeId==="CC" && type==="EF"){alert("Une Contrainte (CC) ne peut contenir que des CC.");return;}
  var parentFbsId = ctxNode.fbsId;
  openCreateUnder(type, parentFbsId);
}
function ctxDelete(){
  hideCtxMenu();
  if(!ctxNode)return;
  if(ctxNode.typeId==="ROOT"){alert("La racine ne peut pas etre detachee.");return;}
  var segs=String(ctxNode.tvId).split(".");
  if(segs.length<2){alert("Cet element n a pas de parent a detacher.");return;}
  var parentFbsId=parseInt(segs[segs.length-2]);
  var childFbsId=ctxNode.fbsId;
  var otherParents=state.pcrm.filter(function(l){return l.childId===childFbsId&&l.parentId!==parentFbsId;}).length;
  var lbl=(ctxNode.typeId==="CC")?"Ce CC":"Cet EF";
  var msg=otherParents>0
    ? lbl+" a plusieurs parents : seul le lien vers ce parent sera retire (il reste rattache ailleurs). Continuer ?"
    : lbl+" a un lien unique dans l arborescence : il va etre bascule dans la liste des Orphelins, d ou il pourra etre supprime definitivement si necessaire. Continuer ?";
  if(!confirm(msg))return;
  state.pcrm=state.pcrm.filter(function(l){return !(l.parentId===parentFbsId&&l.childId===childFbsId);});
  selectedTvId=null;persist();computeNodes();renderTree();
  document.getElementById("detail-scroll").innerHTML="";
}

// Creation d'un element directement rattache a un parent donne
