  var typeCyc=makeCycleField("Type FBS","FBS_Type","EF",{noNeutre:true,onlyVals:["EF","CC"],onChange:function(v){prevEl.textContent="IDU : "+(v==="CC"?"CC-":"EF-")+String(newId).padStart(6,"0");if(window._createTypeLabelsHook)window._createTypeLabelsHook();}});
  row.appendChild(typeCyc);window._createTypeW=typeCyc._getVal;
  var bsCy=makeCycleField("Besoin Client","Besoin_Client","");row.appendChild(bsCy);window._createBesoinW=bsCy._getVal;
