  var caCy=makeCycleField("Application","Application","");row.appendChild(caCy);window._createAppW=caCy._getVal;
  var phCy=makeCycleField("Phase Projet","Phase_Projet","");row.appendChild(phCy);window._createPhaseW=phCy._getVal;
  var compW=makeCompetenceWidget([]);
  var noFF=makeFF("Nom",makeInput("c-no","",""));
  var dcFF=makeFF("Description",makeTextarea("c-dc",""));dcFF.className="ff full ff-tall";
  var lgFF=makeFF("Lignes Guides",makeTextarea("c-lg",""));lgFF.className="ff full ff-tall";
  var iduFF=makeFF("Identifiant personnalise (ex: PRT)",makeInput("c-idu","","Laisser vide pour auto"));
  app(body,row,prevEl,iduFF,noFF,dcFF,lgFF,compW);
  body._compW=compW;window._createCompW=compW._getComps;
