// CHAMP CYCLIQUE (acronymes : neutre -> valeurs de la categorie)
// ============================================================
function makeCycleField(labelTxt, categorie, currentVal, opts){
  opts=opts||{};
  var acrMap=buildAcrMap();
  // Liste ordonnee des valeurs de la categorie
  var vals=(state.acronymes||[]).filter(function(a){return a.categorie===categorie;})
    .sort(function(a,b){return (a.ordre||0)-(b.ordre||0);})
    .map(function(a){return a.id;});
  // Restreindre a certaines valeurs si demande (ex: Type = EF, CC seulement)
  if(opts.onlyVals){vals=vals.filter(function(id){return opts.onlyVals.indexOf(id)>=0;});}
  // cycle = [neutre] + vals (sauf si opts.noNeutre)
  var cycle = opts.noNeutre ? vals.slice() : [""].concat(vals);
  var cur = currentVal||"";
  if(cycle.indexOf(cur)<0) cur = opts.noNeutre?(vals[0]||""):"";

  var wrap=makeEl("div",{"class":"ff"});
  wrap.appendChild(makeEl("label",{},labelTxt));
  var btn=makeEl("button",{type:"button",style:{width:"100%",display:"flex",alignItems:"center",gap:"6px",padding:"6px 10px",borderRadius:"6px",cursor:"pointer",border:"1px solid var(--border2)",background:"var(--bg3)",color:"var(--text)",fontFamily:"inherit",fontSize:"12px",textAlign:"left",minHeight:"34px"}});

  function render(){
    btn.innerHTML="";
    var a=acrMap[cur];
    if(!cur){
      btn.style.borderColor="var(--border2)";
      btn.appendChild(makeEl("span",{style:{color:"var(--text3)"}},"(non defini - cliquer pour choisir)"));
    }else{
      var col=(a&&a.couleur)?a.couleur:"#888";
      btn.style.borderColor=col;
      // icone
      if(a&&acrIconSrc(a)){
        btn.appendChild(makeEl("img",{src:acrIconSrc(a),style:{width:"18px",height:"18px",objectFit:"contain",flexShrink:"0"}}));
      }else{
        btn.appendChild(makeEl("span",{style:{display:"inline-block",width:"12px",height:"12px",borderRadius:"3px",background:col,flexShrink:"0"}}));
      }
      // designation complete
      btn.appendChild(makeEl("span",{style:{color:col,fontWeight:"bold"}},(a&&a.designation)?a.designation:cur));
    }
  }
  btn.onclick=function(){
    var i=cycle.indexOf(cur);
    cur=cycle[(i+1)%cycle.length];
    render();
    if(opts.onChange)opts.onChange(cur);
  };
  render();
  wrap.appendChild(btn);
  wrap._getVal=function(){return cur;};
  return wrap;
}

