function onFileImport(e){
  var file=e.target.files[0];if(!file)return;
  var r=new FileReader();
  r.onload=function(ev){
    try{
      var d=JSON.parse(ev.target.result);
      if(d.fbs&&d.pcrm&&d.acronymes){
        // Effacer d'abord toute trace de l'ancienne base (comme Reset)
        // pour eviter que des donnees en cache ne reprennent le dessus
        try{localStorage.removeItem(SK);}catch(err2){}
        // Reinitialiser tous les filtres et l'etat d'affichage
        filterType="ALL";filterPhase="";filterBesoin="";filterRisque="";filterApplication="";searchStr="";depthLimit=null;
        // Charger la nouvelle base proprement
        state=d;
        if(!state.contractors)state.contractors=[];
        if(!state.sow)state.sow=[];
        if(!state.competences)state.competences=[];
        if(!state.lexique)state.lexique=[];
        if(!state.lexiqueDomaines)state.lexiqueDomaines=[];
        // Sauvegarder immediatement la nouvelle base dans le stockage
        persist();
        // Rafraichir entierement l'interface
        computeNodes();renderTree();
        var ds=document.getElementById("detail-scroll");if(ds)ds.innerHTML="";
        if(typeof updateOrphanCount==="function")updateOrphanCount();
        // Remettre les controles de filtre a zero visuellement
        var ids=["fil-phase","fil-besoin","fil-risque","fil-application","search"];
        ids.forEach(function(id){var el=document.getElementById(id);if(el)el.value="";});
        alert("Import reussi : "+d.fbs.length+" elements charges. L'ancienne base a ete remplacee.");
      }else alert("Format invalide : ce fichier ne contient pas une base FBS complete.");
    }catch(err){alert("Erreur de lecture du JSON : "+err.message);}
  };
  r.readAsText(file);
}
function doReset(){
  if(!window.isAdmin){alert("Reserve aux administrateurs.");return;}
  if(!confirm("Reinitialiser toutes les donnees ?"))return;
  state=clone(INITIAL_RAW);state.contractors=[];state.sow=[];
  filterPhase="";filterBesoin="";filterRisque="";
  try{localStorage.removeItem(SK);}catch(e){}
  computeNodes();renderTree();document.getElementById("detail-scroll").innerHTML="";
  persist();
}


