var LOGO_B64 = "";

function collectVisibleNodes(){
  var rows=[];
  var hasFilter=filterType!=="ALL"||filterPhase||filterBesoin||filterRisque;
  var matchIds=getMatchIds();
  function walk(node,depth){
    if(node.typeId!=="ROOT"){
      if(filterType!=="ALL"&&node.typeId!==filterType){
      } else if(hasFilter&&!subtreeMatchesFilters(node)){
        return;
      } else {
        rows.push({node:node,depth:depth});
      }
    }
    (node.children||[]).forEach(function(c){walk(c,depth+1);});
  }
  treeRoots.forEach(function(r){
    rows.push({node:r,depth:0});
    (r.children||[]).forEach(function(c){walk(c,1);});
  });
  return rows;
}

function filterSummary(){
  var parts=getActiveFiltersText();
  if(!parts.length) return "Aucun filtre (vue complete)";
  return parts.map(function(p){return p.lbl+": "+p.val;}).join("  |  ");
}
function nowStr(){
  var d=new Date();function p(n){return (n<10?"0":"")+n;}
  return p(d.getDate())+"/"+p(d.getMonth()+1)+"/"+d.getFullYear();
}

var wordExportRoot=null;
function collectSubtreeRows(root){
  var rows=[];
  var hasFilter=filterType!=="ALL"||filterPhase||filterBesoin||filterRisque||filterApplication;
  (function walk(node,depth){
    if(filterType!=="ALL"&&node.typeId!==filterType){
      // type non correspondant : on n ajoute pas ce noeud mais on descend
    } else if(hasFilter&&!subtreeMatchesFilters(node)){
      return; // ni ce noeud ni ses descendants ne correspondent au filtre
    } else {
      rows.push({node:node,depth:depth});
    }
    (node.children||[]).forEach(function(c){walk(c,depth+1);});
  })(root,0);
  return rows;
}
