  var fileName=(subRoot?("UrBizia_Prompt_"+String(subRoot.idu||subRoot.no||"EF").replace(/[^A-Za-z0-9_-]/g,"_")+"_"):"UrBizia_Prompt_")+new Date().toISOString().slice(0,10)+".docx";

  function colOf(id,def){var a=acrMap[id];var c=(a&&a.couleur)?a.couleur:def;return c.replace("#","");}
  // Run icone (image) si dispo, sinon petit texte colore
