async function refreshFromSupabase(){
  if(!currentUserId) return;
  try{
    var results = await Promise.all([
      sb.from("fbs").select("*"),
      sb.from("pcrm").select("*"),
      sb.from("acronymes").select("*"),
      sb.from("competences").select("label"),
      sb.from("lexique").select("*"),
      sb.from("lexique_domaines").select("label"),
      sb.from("contractors").select("*"),
      sb.from("sow").select("*"),
      sb.rpc("has_tool_access",{p_tool:"fbs",p_min_role:"admin"})
    ]);
    var fbsR=results[0], pcrmR=results[1], acrR=results[2], compR=results[3], lexR=results[4], lexDomR=results[5], ctrR=results[6], sowR=results[7], adminR=results[8];
    state.fbs=(fbsR.data||[]).map(function(r){return {id:r.id, idu:r.idu, typeId:r.type_id, no:r.no, dc:r.dc, lg:r.lg, ref:r.ref, refOrig:r.ref_orig, phase:r.phase, besoin:r.besoin, risque:r.risque, competences:r.competences||[], application:r.application, illustrations:r.illustrations||[]};});
    state.pcrm=(pcrmR.data||[]).map(function(r){return {childId:r.child_id, parentId:(r.parent_id===null?0:r.parent_id), ord:r.ord};});
    state.acronymes=(acrR.data||[]).map(function(r){return {id:r.id, categorie:r.categorie, ordre:r.ordre, designation:r.designation, couleur:r.couleur, iconBase64:r.icon_base64, iconSvg:r.icon_svg};});
    state.competences=(compR.data||[]).map(function(r){return r.label;});
    state.lexique=(lexR.data||[]).map(function(r){return {expression:r.expression, equivalence:r.equivalence, acronyme:r.acronyme, domaines:r.domaines||[], definition:r.definition};});
    state.lexiqueDomaines=(lexDomR.data||[]).map(function(r){return r.label;});
    state.contractors=(ctrR.data||[]).map(function(r){return {id:r.id, nom:r.nom, contact:r.contact};});
    state.sow=(sowR.data||[]).map(function(r){return {ct:r.contractor_id, fbsId:r.fbs_id, inScope:r.in_scope, mi:r.mi, sf:r.sf, rd:r.rd, vp:r.vp, td:r.td, etpsem:r.etpsem, remarques:r.remarques, wp:r.wp};});
    window.isAdmin = !!(adminR && adminR.data);
    updateAdminUI();
    computeNodes(); renderTree();
    var ds=document.getElementById("detail-scroll"); if(ds) ds.innerHTML="";
  }catch(e){
    console.error("refreshFromSupabase failed", e);
    alert("Erreur lors du chargement des donnees depuis Supabase : "+(e.message||e));
  }
}

async function persistToSupabase(){
  if(!currentUserId) return;
  try{
    var ctRows=(state.contractors||[]).map(function(c){return {id:c.id, nom:c.nom||c.shortName||c.id, contact:c.contact||"", owner_id:currentUserId};});
    var sowRows=(state.sow||[]).map(function(s){return {contractor_id:s.ct, fbs_id:s.fbsId, in_scope:!!s.inScope, mi:s.mi||"", sf:s.sf||"", rd:s.rd||"", vp:s.vp||"", td:s.td||"", etpsem:s.etpsem||"", remarques:s.remarques||"", wp:s.wp||"", owner_id:currentUserId};});
    if(ctRows.length) await sb.from("contractors").upsert(ctRows);
    if(sowRows.length) await sb.from("sow").upsert(sowRows,{onConflict:"contractor_id,fbs_id"});
    var existingCt=(await sb.from("contractors").select("id").eq("owner_id",currentUserId)).data||[];
    var keepCtIds=ctRows.map(function(r){return r.id;});
    var toDeleteCt=existingCt.filter(function(r){return keepCtIds.indexOf(r.id)===-1;}).map(function(r){return r.id;});
    if(toDeleteCt.length) await sb.from("contractors").delete().in("id",toDeleteCt);
    var existingSow=(await sb.from("sow").select("id, contractor_id, fbs_id").eq("owner_id",currentUserId)).data||[];
    var keepPairs={}; sowRows.forEach(function(r){keepPairs[r.contractor_id+"|"+r.fbs_id]=true;});
    var toDeleteSowIds=existingSow.filter(function(r){return !keepPairs[r.contractor_id+"|"+r.fbs_id];}).map(function(r){return r.id;});
    if(toDeleteSowIds.length) await sb.from("sow").delete().in("id",toDeleteSowIds);
  }catch(e){console.error("persistToSupabase failed",e);}
  if(window.isAdmin) await syncReferenceToSupabase();
}

async function syncReferenceToSupabase(){
  // Acronymes/Competences/Lexique/Lexique_domaines sont desormais geres depuis le
  // panneau Administration d EkoMa (ecriture directe par ligne) : ce full-replace ne
  // doit plus y toucher, sous peine d ecraser silencieusement une modification recente
  // faite depuis EkoMa a chaque sauvegarde d une fiche FBS.
  if(!window.isAdmin) return;
  try{
    await sb.from("pcrm").delete().neq("id",-1);
    await sb.from("fbs").delete().neq("id",-1);
    var fbsRows=(state.fbs||[]).map(function(f){return {id:f.id, idu:f.idu, type_id:f.typeId, no:f.no, dc:f.dc, lg:f.lg, ref:f.ref, ref_orig:f.refOrig, phase:f.phase, besoin:f.besoin, risque:f.risque, competences:f.competences||[], application:f.application, illustrations:f.illustrations||[]};});
    if(fbsRows.length) await sb.from("fbs").insert(fbsRows);
    var pcrmRows=(state.pcrm||[]).map(function(p){return {child_id:p.childId, parent_id:(p.parentId===0?null:p.parentId), ord:p.ord};});
    if(pcrmRows.length) await sb.from("pcrm").insert(pcrmRows);
  }catch(e){
    console.error("syncReferenceToSupabase failed",e);
    alert("Erreur de synchronisation Supabase : "+(e.message||e));
  }
}

// ===== Gate d'acces EkoMa (auth-gate.js, partage avec RFQ) =====
// Remplace l'ancien bloc dupliqué showAuthOverlay/hideAuthOverlay/onAuthenticated/
// onAuthStateChange/verification de session au chargement. Voir auth-gate.js pour le contrat.
var gate = initEkoGate({
  sb: sb,
  tool: "fbs",
  deniedMessage: "Ce compte n'a pas acces a FBS. Contactez l'administrateur.",
  onGranted: async function(user){
    currentUserId = user.id;
    await refreshFromSupabase();
    maybeRunBackup();
  },
  onSignedOut: function(){
    currentUserId = null;
    window.isAdmin = false;
  }
});
